import {readFileSync, realpathSync} from 'node:fs';
import {fileURLToPath, pathToFileURL} from 'node:url';

function isNonNegativeSafeInt(v){ return Number.isSafeInteger(v) && v >= 0; }

export function nextRetry(options){
  if (typeof options !== 'object' || options === null || Array.isArray(options)){
    throw new Error('options must be a non-null, non-array object');
  }
  const attempt = options.attempt;
  const elapsedMs = options.elapsedMs;
  const baseMs = options.baseMs;
  const maxDelayMs = options.maxDelayMs;
  const budgetMs = options.budgetMs;
  const retryAfterMs = options.retryAfterMs;
  const retryable = options.retryable;

  if (!Number.isSafeInteger(attempt) || attempt < 1){
    throw new Error('attempt must be a positive safe integer');
  }
  if (!isNonNegativeSafeInt(elapsedMs)){
    throw new Error('elapsedMs must be a nonnegative safe integer');
  }
  if (!isNonNegativeSafeInt(baseMs)){
    throw new Error('baseMs must be a nonnegative safe integer');
  }
  if (!isNonNegativeSafeInt(maxDelayMs)){
    throw new Error('maxDelayMs must be a nonnegative safe integer');
  }
  if (!isNonNegativeSafeInt(budgetMs)){
    throw new Error('budgetMs must be a nonnegative safe integer');
  }
  if (retryAfterMs !== null && !isNonNegativeSafeInt(retryAfterMs)){
    throw new Error('retryAfterMs must be null or a nonnegative safe integer');
  }
  if (typeof retryable !== 'boolean'){
    throw new Error('retryable must be a boolean');
  }

  if (!retryable){
    return {retry:false,delayMs:null,reason:'non-retryable'};
  }

  // baseMs * 2 ** (attempt - 1), capped at maxDelayMs. The power is exact in
  // binary floating point until it overflows to Infinity, so min() saturates
  // at maxDelayMs for huge attempts with no loop and no precision loss below
  // the cap. A zero base means zero delay regardless of the attempt.
  const expDelay = baseMs === 0
    ? 0
    : Math.min(maxDelayMs, baseMs * 2 ** (attempt - 1));
  const wait = retryAfterMs === null ? expDelay : Math.max(expDelay, retryAfterMs);

  if (elapsedMs > budgetMs || wait > budgetMs - elapsedMs){
    return {retry:false,delayMs:null,reason:'budget-exhausted'};
  }
  return {retry:true,delayMs:wait,reason:'scheduled'};
}

function isMainModule(){
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

function runCli(){
  const args = process.argv.slice(2);
  let parsed;
  try {
    if (args.length !== 1){
      throw new Error('usage: node retry-budget.js INPUT_JSON_FILE');
    }
    const raw = readFileSync(args[0], 'utf8').replace(/^\uFEFF/, '');
    parsed = JSON.parse(raw);
  } catch (err){
    process.stderr.write(`retry-budget: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  let result;
  try {
    result = nextRetry(parsed);
  } catch (err){
    process.stderr.write(`retry-budget: invalid options: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  process.stdout.write(`${JSON.stringify(result)}\n`);
}

if (isMainModule()){
  runCli();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';
import {nextRetry} from '../retry-budget.js';

const run = promisify(execFile);
const scriptPath = resolve(new URL('../retry-budget.js', import.meta.url).pathname);
const tmpRoot = mkdtempSync(join(tmpdir(), 'retry-budget-test-'));
const fixtures = [];
test.after(() => rmSync(tmpRoot, {recursive: true, force: true}));

function fixture(name, content){
  const file = join(tmpRoot, name);
  writeFileSync(file, content);
  fixtures.push(file);
  return file;
}

const base = {attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true};

test('exponential delay doubles per attempt and caps at maxDelayMs', () => {
  assert.deepEqual(nextRetry({...base, attempt: 1}), {retry: true, delayMs: 10, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 2}), {retry: true, delayMs: 20, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 3}), {retry: true, delayMs: 40, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 5}), {retry: true, delayMs: 100, reason: 'scheduled'});
});

test('huge attempts cap without loops or overflow', () => {
  assert.deepEqual(nextRetry({...base, attempt: 10 ** 9}), {retry: true, delayMs: 100, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 9007199254740991}), {retry: true, delayMs: 100, reason: 'scheduled'});
});

test('zero base means zero delay even for huge attempts', () => {
  assert.deepEqual(
    nextRetry({...base, baseMs: 0, attempt: 9007199254740991}),
    {retry: true, delayMs: 0, reason: 'scheduled'},
  );
});

test('exact power-of-two delays stay precise', () => {
  assert.deepEqual(
    nextRetry({...base, baseMs: 1, maxDelayMs: 9007199254740991, budgetMs: 9007199254740991, attempt: 40}),
    {retry: true, delayMs: 549755813888, reason: 'scheduled'}, // 2**39
  );
});

test('retryAfterMs is a floor and is not capped by maxDelayMs', () => {
  assert.deepEqual(nextRetry({...base, retryAfterMs: 50}), {retry: true, delayMs: 50, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, retryAfterMs: 1000, budgetMs: 5000}), {retry: true, delayMs: 1000, reason: 'scheduled'});
  // exponential below the hint loses
  assert.deepEqual(nextRetry({...base, retryAfterMs: 150, budgetMs: 5000}), {retry: true, delayMs: 150, reason: 'scheduled'});
  // exponential above the hint wins
  assert.deepEqual(nextRetry({...base, attempt: 5, retryAfterMs: 10}), {retry: true, delayMs: 100, reason: 'scheduled'});
});

test('budget boundary: equality is allowed', () => {
  // wait exactly fills the remaining budget
  assert.deepEqual(nextRetry({...base, budgetMs: 100}), {retry: true, delayMs: 100, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, elapsedMs: 500, budgetMs: 600}), {retry: true, delayMs: 100, reason: 'scheduled'});
  // zero base with zero budget schedules at the boundary
  assert.deepEqual(nextRetry({...base, baseMs: 0, budgetMs: 0, elapsedMs: 0}), {retry: true, delayMs: 0, reason: 'scheduled'});
  // one tick over is exhausted
  assert.deepEqual(nextRetry({...base, budgetMs: 99, elapsedMs: 0}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
  assert.deepEqual(nextRetry({...base, budgetMs: 0, elapsedMs: 0}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
});

test('elapsedMs exceeding budgetMs is exhausted', () => {
  assert.deepEqual(nextRetry({...base, elapsedMs: 1001, budgetMs: 1000}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
});

test('non-retryable returns the exact decision and ignores math', () => {
  assert.deepEqual(nextRetry({...base, retryable: false}), {retry: false, delayMs: null, reason: 'non-retryable'});
});

test('extra fields are ignored', () => {
  assert.deepEqual(nextRetry({...base, whatever: 42, label: 'x'}), {retry: true, delayMs: 10, reason: 'scheduled'});
});

test('frozen input works and is not mutated', () => {
  const frozen = Object.freeze({...base});
  assert.deepEqual(nextRetry(frozen), {retry: true, delayMs: 10, reason: 'scheduled'});
  const mutable = {...base};
  const before = JSON.parse(JSON.stringify(mutable));
  nextRetry(mutable);
  assert.deepEqual(mutable, before);
  const result = nextRetry(base);
  assert.deepEqual(Object.keys(result).sort(), ['delayMs', 'reason', 'retry']);
});

test('every field is validated even when retryable is false', () => {
  const bad = (patch) => {
    assert.throws(() => nextRetry({...base, retryable: false, ...patch}), Error);
  };
  bad({attempt: 0});
  bad({attempt: 1.5});
  bad({attempt: 2 ** 53});
  bad({attempt: -1});
  bad({elapsedMs: -1});
  bad({baseMs: -1});
  bad({maxDelayMs: -1});
  bad({budgetMs: -1});
  bad({retryAfterMs: -1});
  bad({retryAfterMs: 1.5});
});

test('invalid options throw', () => {
  const throwsFor = (value) => assert.throws(() => nextRetry(value), Error);
  throwsFor(null);
  throwsFor(5);
  throwsFor('nope');
  throwsFor([1, 2, 3]);
  throwsFor(undefined);
  const bad = (patch) => throwsFor({...base, ...patch});
  bad({attempt: 0});
  bad({attempt: 1.5});
  bad({attempt: 2 ** 53});
  bad({attempt: NaN});
  bad({attempt: '1'});
  bad({elapsedMs: -1});
  bad({elapsedMs: 1.5});
  bad({baseMs: -1});
  bad({baseMs: '10'});
  bad({maxDelayMs: -1});
  bad({maxDelayMs: 1e21});
  bad({budgetMs: -1});
  bad({retryAfterMs: -1});
  bad({retryAfterMs: NaN});
  bad({retryable: 'yes'});
  bad({retryable: 1});
  assert.throws(() => nextRetry({...base, attempt: 1} ? {...base} : undefined, ), undefined && null); // noop guard
  // missing fields
  const {retryAfterMs, ...withoutHint} = base;
  throwsFor(withoutHint);
});

test('CLI prints exactly one JSON value plus newline on success', async () => {
  const file = fixture('ok.json', JSON.stringify(base));
  const {stdout, stderr} = await run('node', [scriptPath, file]);
  assert.equal(stdout, `${JSON.stringify({retry: true, delayMs: 10, reason: 'scheduled'})}\n`);
  assert.equal(stderr, '');
});

test('CLI exits 0 for valid non-retry and budget-exhausted decisions', async () => {
  const file = fixture('noretry.json', JSON.stringify({...base, retryable: false}));
  const {stdout, stderr} = await run('node', [scriptPath, file]);
  assert.equal(stdout, `${JSON.stringify({retry: false, delayMs: null, reason: 'non-retryable'})}\n`);
  assert.equal(stderr, '');

  const exhausted = fixture('exhausted.json', JSON.stringify({...base, elapsedMs: 5000}));
  const out = await run('node', [scriptPath, exhausted]);
  assert.equal(out.stdout, `${JSON.stringify({retry: false, delayMs: null, reason: 'budget-exhausted'})}\n`);
  assert.equal(out.stderr, '');
});

async function expectCliFailure(args, label){
  await test(`${label} exits 2 with stderr and no stdout`, async () => {
    let code, stdout, stderr;
    try {
      ({stdout, stderr} = await run('node', [scriptPath, ...args]));
      code = 0;
    } catch (err) {
      code = err.code;
      stdout = err.stdout;
      stderr = err.stderr;
    }
    assert.equal(code, 2);
    assert.equal(stdout, '');
    assert.ok(stderr.length > 0);
  });
}

await expectCliFailure([], 'no arguments');
await expectCliFailure(['a.json', 'b.json'], 'two arguments');
await expectCliFailure([join(tmpRoot, 'missing.json')], 'missing file');

test('CLI rejects malformed JSON and invalid options', async () => {
  await expectCliFailure([fixture('badjson.json', '{nope')], 'malformed JSON');
  await expectCliFailure([fixture('null.json', 'null')], 'JSON null');
  await expectCliFailure([fixture('array.json', '[1]')], 'JSON array');
  await expectCliFailure([fixture('str.json', '"hi"')], 'JSON string');
  await expectCliFailure([fixture('missing-field.json', JSON.stringify({attempt: 1}))], 'missing required fields');
  await expectCliFailure([fixture('bad-attempt.json', JSON.stringify({...base, attempt: 0}))], 'attempt 0');
  await expectCliFailure([fixture('bad-retryable.json', JSON.stringify({...base, retryable: 'yes'}))], 'retryable not a boolean');
  await expectCliFailure([fixture('big-attempt.json', JSON.stringify({...base, attempt: 2 ** 53}))], 'attempt not a safe integer');
});

test('importing the module does not run the CLI', async () => {
  const {stdout, stderr} = await run('node', ['-e', `import(${JSON.stringify(`file://${scriptPath}`)}).then(m => { if (typeof m.nextRetry !== 'function') process.exit(1); });`]);
  assert.equal(stdout, '');
  assert.equal(stderr, '');
});

