import test from 'node:test';
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';
import {nextRetry} from '../retry-budget.js';

const run = promisify(execFile);
const scriptPath = resolve(new URL('../retry-budget.js', import.meta.url).pathname);

// Each test owns its own tmpdir and always removes it, even on assertion
// failure, so parallel test files cannot interfere and nothing is left behind.
async function withFixture(name, content, fn){
  const dir = mkdtempSync(join(tmpdir(), 'retry-budget-test-'));
  try {
    const file = join(dir, name);
    writeFileSync(file, content);
    return await fn(file);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
}

async function cli(args, label){
  let code, stdout, stderr;
  try {
    ({stdout, stderr} = await run('node', [scriptPath, ...args]));
    code = 0;
  } catch (err) {
    code = err.code;
    stdout = err.stdout;
    stderr = err.stderr;
  }
  return {code, stdout, stderr, label};
}

async function expectCliSuccess(file, expected){
  const {code, stdout, stderr} = await cli([file], 'cli success');
  assert.equal(code, 0);
  assert.equal(stdout, `${JSON.stringify(expected)}\n`);
  assert.equal(stderr, '');
}

async function expectCliFailure(args, label){
  const {code, stdout, stderr} = await cli(args, label);
  assert.equal(code, 2, `${label}: expected exit code 2, got ${code}; stderr=${stderr}`);
  assert.equal(stdout, '', `${label}: expected empty stdout, got ${JSON.stringify(stdout)}`);
  assert.ok(stderr.length > 0, `${label}: expected nonempty stderr`);
}

const base = {attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true};

test('exponential delay doubles per attempt and caps at maxDelayMs', () => {
  assert.deepEqual(nextRetry({...base, attempt: 1}), {retry: true, delayMs: 10, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 2}), {retry: true, delayMs: 20, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 3}), {retry: true, delayMs: 40, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 5}), {retry: true, delayMs: 100, reason: 'scheduled'});
});

test('huge attempts cap without loops or overflow', () => {
  assert.deepEqual(nextRetry({...base, attempt: 10 ** 9}), {retry: true, delayMs: 100, reason: 'scheduled'});
  assert.deepEqual(nextRetry({...base, attempt: 9007199254740991}), {retry: true, delayMs: 100, reason: 'scheduled'});
});

test('zero base means zero delay even for huge attempts', () => {
  assert.deepEqual(
    nextRetry({...base, baseMs: 0, attempt: 9007199254740991}),
    {retry: true, delayMs: 0, reason: 'scheduled'},
  );
});

test('exact power-of-two delays stay precise', () => {
  assert.deepEqual(
    nextRetry({...base, baseMs: 1, maxDelayMs: 9007199254740991, budgetMs: 9007199254740991, attempt: 40}),
    {retry: true, delayMs: 549755813888, reason: 'scheduled'}, // 2**39
  );
});

test('retryAfterMs is a floor and is not capped by maxDelayMs', () => {
  assert.deepEqual(nextRetry({...base, retryAfterMs: 50}), {retry: true, delayMs: 50, reason: 'scheduled'});
  // hint above maxDelayMs is honored, not capped
  assert.deepEqual(nextRetry({...base, retryAfterMs: 1000, budgetMs: 5000}), {retry: true, delayMs: 1000, reason: 'scheduled'});
  // exponential below the hint loses
  assert.deepEqual(nextRetry({...base, retryAfterMs: 150, budgetMs: 5000}), {retry: true, delayMs: 150, reason: 'scheduled'});
  // exponential above the hint wins
  assert.deepEqual(nextRetry({...base, attempt: 5, retryAfterMs: 10}), {retry: true, delayMs: 100, reason: 'scheduled'});
  // hint at zero behaves like the exponential value
  assert.deepEqual(nextRetry({...base, retryAfterMs: 0}), {retry: true, delayMs: 10, reason: 'scheduled'});
});

test('budget boundary: equality is allowed', () => {
  // wait exactly fills the whole budget
  assert.deepEqual(nextRetry({...base, attempt: 5, budgetMs: 100}), {retry: true, delayMs: 100, reason: 'scheduled'});
  // wait exactly fills the remaining budget
  assert.deepEqual(nextRetry({...base, elapsedMs: 500, budgetMs: 600}), {retry: true, delayMs: 100, reason: 'scheduled'});
  // zero base with zero budget schedules exactly at the boundary
  assert.deepEqual(nextRetry({...base, baseMs: 0, budgetMs: 0, elapsedMs: 0}), {retry: true, delayMs: 0, reason: 'scheduled'});
  // hint scheduling exactly at the boundary
  assert.deepEqual(nextRetry({...base, retryAfterMs: 990, budgetMs: 990}), {retry: true, delayMs: 990, reason: 'scheduled'});
  // one tick over is exhausted
  assert.deepEqual(nextRetry({...base, attempt: 5, budgetMs: 99}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
  assert.deepEqual(nextRetry({...base, elapsedMs: 501, budgetMs: 600}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
  assert.deepEqual(nextRetry({...base, budgetMs: 0}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
});

test('elapsedMs exceeding budgetMs is exhausted', () => {
  assert.deepEqual(nextRetry({...base, elapsedMs: 1001, budgetMs: 1000}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
  // equal elapsed/budget is not "exceeds"; the wait still decides
  assert.deepEqual(nextRetry({...base, elapsedMs: 1000, budgetMs: 1000}), {retry: false, delayMs: null, reason: 'budget-exhausted'});
});

test('non-retryable returns the exact decision and ignores math', () => {
  assert.deepEqual(nextRetry({...base, retryable: false}), {retry: false, delayMs: null, reason: 'non-retryable'});
  // even an unbounded hint cannot make it retry
  assert.deepEqual(nextRetry({...base, retryable: false, retryAfterMs: 1}), {retry: false, delayMs: null, reason: 'non-retryable'});
});

test('extra fields are ignored', () => {
  assert.deepEqual(nextRetry({...base, whatever: 42, label: 'x', [Symbol.for('x')]: 1}), {retry: true, delayMs: 10, reason: 'scheduled'});
});

test('frozen input works and is not mutated', () => {
  const frozen = Object.freeze({...base, retryAfterMs: null});
  assert.deepEqual(nextRetry(frozen), {retry: true, delayMs: 10, reason: 'scheduled'});
  const mutable = {...base};
  const before = JSON.parse(JSON.stringify(mutable));
  nextRetry(mutable);
  assert.deepEqual(mutable, before);
  const result = nextRetry(base);
  assert.deepEqual(Object.keys(result).sort(), ['delayMs', 'reason', 'retry']);
});

test('every field is validated even when retryable is false', () => {
  const bad = (patch) => {
    assert.throws(() => nextRetry({...base, retryable: false, ...patch}), Error);
  };
  bad({attempt: 0});
  bad({attempt: 1.5});
  bad({attempt: 2 ** 53});
  bad({attempt: -1});
  bad({elapsedMs: -1});
  bad({elapsedMs: 1.5});
  bad({baseMs: -1});
  bad({maxDelayMs: -1});
  bad({budgetMs: -1});
  bad({budgetMs: 1.5});
  bad({retryAfterMs: -1});
  bad({retryAfterMs: 1.5});
});

test('invalid options throw', () => {
  const throwsFor = (value) => assert.throws(() => nextRetry(value), Error);
  throwsFor(null);
  throwsFor(undefined);
  throwsFor(5);
  throwsFor('nope');
  throwsFor([1, 2, 3]);
  const bad = (patch) => throwsFor({...base, ...patch});
  bad({attempt: 0});
  bad({attempt: 1.5});
  bad({attempt: 2 ** 53});
  bad({attempt: NaN});
  bad({attempt: '1'});
  bad({attempt: -1});
  bad({elapsedMs: -1});
  bad({elapsedMs: 1.5});
  bad({elapsedMs: null});
  bad({baseMs: -1});
  bad({baseMs: '10'});
  bad({maxDelayMs: -1});
  bad({maxDelayMs: 1e21});
  bad({budgetMs: -1});
  bad({retryAfterMs: -1});
  bad({retryAfterMs: NaN});
  bad({retryable: 'yes'});
  bad({retryable: 1});
  bad({retryable: null});
  // missing required fields
  for (const key of ['attempt', 'elapsedMs', 'baseMs', 'maxDelayMs', 'budgetMs', 'retryable']) {
    const {attempt, elapsedMs, baseMs, maxDelayMs, budgetMs, retryable, ...rest} = base;
    throwsFor(key === 'attempt' ? {...rest, elapsedMs, baseMs, maxDelayMs, budgetMs, retryable} : {...base, [key]: undefined});
  }
  const {attempt, elapsedMs, baseMs, maxDelayMs, budgetMs, retryable, ...withoutRetryable} = base;
  throwsFor({...attempt: 1, ...withoutRetryable});
