});

test('invalid options throw', () => {
  const throwsFor = (value) => assert.throws(() => nextRetry(value), Error);
  throwsFor(null);
  throwsFor(undefined);
  throwsFor(5);
  throwsFor('nope');
  throwsFor([1, 2, 3]);
  const bad = (patch) => throwsFor({...base, ...patch});
  bad({attempt: 0});
  bad({attempt: 1.5});
  bad({attempt: 2 ** 53});
  bad({attempt: NaN});
  bad({attempt: '1'});
  bad({attempt: -1});
  bad({elapsedMs: -1});
  bad({elapsedMs: 1.5});
  bad({elapsedMs: null});
  bad({baseMs: -1});
  bad({baseMs: '10'});
  bad({maxDelayMs: -1});
  bad({maxDelayMs: 1e21});
  bad({budgetMs: -1});
  bad({retryAfterMs: -1});
  bad({retryAfterMs: NaN});
