    ['badjson.json', '{nope', 'malformed JSON'],
    ['null.json', 'null', 'JSON null'],
    ['array.json', '[1]', 'JSON array'],
    ['str.json', '"hi"', 'JSON string'],
    ['missing-field.json', JSON.stringify({attempt: 1}), 'missing required fields'],
    ['bad-attempt.json', JSON.stringify({...base, attempt: 0}), 'attempt 0'],
    ['bad-retryable.json', JSON.stringify({...base, retryable: 'yes'}), 'retryable not a boolean'],
    ['big-attempt.json', JSON.stringify({...base, attempt: 2 ** 53}), 'attempt not a safe integer'],
    ['negative-base.json', JSON.stringify({...base, baseMs: -1}), 'negative baseMs'],
  ];
  for (const [name, content, label] of cases) {
