});

test('importing the module does not run the CLI', async () => {
  let code, stdout, stderr;
  try {
    ({stdout, stderr} = await run('node', [
      '-e',
      `import(${JSON.stringify(`file://${scriptPath}`)}).then(m => { if (typeof m.nextRetry !== 'function') process.exit(1); });`,
    ]));
    code = 0;
  } catch (err) {
    code = err.code;
    stdout = err.stdout;
    stderr = err.stderr;
  }
  assert.equal(code, 0);
  assert.equal(stdout, '');
  assert.equal(stderr, '');
});

